def calculate_average(numbers=None):
    # Handle the default parameter case for an empty or None list
    if numbers is None or len(numbers) == 0:
        return 0

    valid_numbers = []

    # Loop through the list and check if each item is a number (int or float)
    for item in numbers:
        if isinstance(item, (int, float)):
            valid_numbers.append(item)

    # Check if we have any valid numbers to avoid division by zero
    if len(valid_numbers) == 0:
        return 0

    return sum(valid_numbers) / len(valid_numbers)

